export default {
  maxMinutes: 120,

  bookings: [
    { id: "B1", start: "2026-12-01T10:00:00+05:00", end: "2026-12-01T11:00:00+05:00" },
    { id: "B2", start: "2026-12-01T13:00:00+05:00", end: "2026-12-01T14:30:00+05:00" }
  ],

  fail(code, message) {
    return { available: false, reasonCode: code, message: message };
  },

  check() {
    const raw = (StartInput.text || "").trim();
    const startDate = raw === "" ? null : new Date(raw);

    if (!startDate || isNaN(startDate.getTime())) {
      return this.fail("INVALID_START", "Please enter a valid start time, for example 2026-12-01T11:30.");
    }

    if (startDate.getTime() <= new Date().getTime()) {
      return this.fail("PAST_START", "The start time must be in the future.");
    }

    const rawDuration = (DurationInput.text || "").toString().trim();
    const duration = rawDuration === "" ? NaN : Number(rawDuration);

    if (isNaN(duration) || !Number.isInteger(duration)) {
      return this.fail("INVALID_DURATION", "Duration must be a whole number of minutes.");
    }
    if (duration <= 0) {
      return this.fail("INVALID_DURATION", "Duration must be greater than zero.");
    }
    if (duration > this.maxMinutes) {
      return this.fail("DURATION_TOO_LONG", "Duration cannot be longer than 120 minutes.");
    }

    if (BlockedSwitch.isSwitchedOn) {
      return this.fail("BLOCKED", "The room is blocked, so it cannot be booked.");
    }

    const endDate = new Date(startDate.getTime() + duration * 60000);
    const conflict = this.bookings.find(function (b) {
      return startDate < new Date(b.end) && endDate > new Date(b.start);
    });

    if (conflict) {
      return this.fail("OVERLAP", "This time overlaps with the existing booking " + conflict.id + ".");
    }

    return { available: true, reasonCode: "OK", message: "The room is free for the selected time." };
  }
}
